<x-layout title="Shopping bag | Clovic"><div class="content-wrap cart-page"><div class="breadcrumb"><a href="/">Home</a><span>/</span>Shopping bag</div><div class="page-heading compact"><span class="eyebrow">YOUR EVERYDAY, IN THE MAKING</span><h1>Your shopping bag.</h1><p>A few considered choices. Ready when you are.</p></div><div class="checkout-grid" x-show="$store.cart.items.length"><section aria-label="Shopping bag items"><p class="field-error" x-show="$store.cart.error" x-text="$store.cart.error" role="alert"></p><template x-for="item in $store.cart.items" :key="item.id"><article class="cart-line"><a :href="item.url"><img :src="item.image" :alt="item.name" width="120" height="150"></a><div><h2><a :href="item.url" x-text="item.name"></a></h2><p><span x-text="item.size"></span> / <span x-text="item.color"></span> · <span x-text="item.sku"></span></p><p x-text="item.unit_price_label+' each'"></p><div class="drawer-item-controls"><div class="stepper"><button @click="$store.cart.change(item,item.quantity-1)" :disabled="$store.cart.busy" :aria-label="'Decrease '+item.name">−</button><span x-text="item.quantity"></span><button @click="$store.cart.change(item,item.quantity+1)" :disabled="$store.cart.busy||item.quantity>=item.max" :aria-label="'Increase '+item.name">+</button></div><button class="remove-button" @click="$store.cart.change(item,0)" :disabled="$store.cart.busy">Remove</button></div></div><strong x-text="item.total_label"></strong></article></template><a href="/shop" class="text-link">← Continue shopping</a></section><aside class="order-summary"><span class="eyebrow">THE FINAL DETAILS</span><h2>Order summary</h2><div class="summary-row"><span>Subtotal</span><strong x-text="$store.cart.subtotal_label">{{ \App\Services\Settings::money($subtotal) }}</strong></div><div class="summary-row"><span>Delivery estimate</span><span>{{ \App\Services\Settings::money((int)($store['delivery_inside']??8000)) }}–{{ \App\Services\Settings::money((int)($store['delivery_outside']??15000)) }}</span></div><p>Choose your delivery region and apply a coupon at checkout. We’ll confirm the final total before you place your order.</p><a href="/checkout" class="button full">Continue to checkout ↗</a><div class="summary-assurance"><i data-lucide="banknote"></i><span>Guest checkout · Cash on Delivery</span></div><a href="/return-exchange-policy" class="small">Returns & exchanges ↗</a></aside></div><div class="empty cart-empty" x-show="!$store.cart.items.length"><i data-lucide="shopping-bag"></i><span class="eyebrow">A FRESH START</span><h2>A little room for something good.</h2><p>Your bag is empty. Let’s find your next everyday essential.</p><a class="button" href="/shop">Explore the collection ↗</a></div><noscript>@foreach($lines as $line)<article class="cart-line"><h2>{{ $line['variant']->product->name }}</h2><form action="/cart" method="post">@csrf<input type="hidden" name="variant_id" value="{{ $line['variant']->id }}"><label>Quantity<input type="number" name="quantity" min="0" max="99" value="{{ $line['quantity'] }}"></label><button class="button">Update bag</button></form></article>@endforeach</noscript></div></x-layout>